// claude-sonnet-5: 1M in + 1M out = $18.00.
func TestParseSessionUnusableReportedCostFallsBackToEstimate(t *testing.T) {
	for _, tc := range []struct {
		name       string
		costUSD    string
		costSource string
	}{
		{"source is the CLI's own estimate", "123.45", `"estimated"`},
		{"source is an unrecognised label", "123.45", `"provider-api"`},
		{"source absent", "123.45", `""`},
		{"value negative", "-1.0", `"reported"`},
		{"value over column range", "100000000.0", `"reported"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
