func TestIntegrationPayloadPhaseGuardRejectsLateSkeleton(t *testing.T) {
	_, st := openTest(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Second)
	skeleton := MyActivityRow{
		AccountID: uid("acc1"), Type: "checkpoint", RepoID: uid("r1"), Jurisdiction: "us",
		SHA: hsha("sha1"), CheckpointID: "cp1", CommittedAt: now,
		Agent: "unknown", HasCheckpoint: true, State: StateShipped, StateSeq: 100,
	}
	hydrated := skeleton
	hydrated.PayloadHydrated = true
	hydrated.Agent = "codex"
	hydrated.InputTokens, hydrated.OutputTokens = 101, 202
	hydrated.CacheCreationTokens, hydrated.CacheReadTokens = 303, 404
	hydrated.Steps, hydrated.SessionCount = 7, 2
	hydrated.SessionIDs = MarshalSessionIDs([]string{"session-1", "session-2"})
	hydrated.Additions, hydrated.Deletions, hydrated.FilesChanged = 10, 3, 2
	hydrated.StateSeq = 500

	lateSkeleton := skeleton
	lateSkeleton.StateSeq = 900 // the race in the finding: stale payload, newer publish
	corrected := hydrated
	corrected.Agent, corrected.Steps, corrected.StateSeq = "claude", 8, 700
	for _, row := range []MyActivityRow{skeleton, hydrated, lateSkeleton, corrected} {
		if err := st.UpsertMyActivity(ctx, row); err != nil {
			t.Fatal(err)
		}
	}
	rows, err := st.ListMyActivity(ctx, ActivityQuery{AccountID: uid("acc1")})
	if err != nil || len(rows) != 1 {
		t.Fatalf("list: err=%v rows=%d", err, len(rows))
	}
	got := rows[0]
	if !got.PayloadHydrated || got.Agent != corrected.Agent || got.InputTokens != corrected.InputTokens || got.OutputTokens != corrected.OutputTokens ||
		got.CacheCreationTokens != corrected.CacheCreationTokens || got.CacheReadTokens != corrected.CacheReadTokens ||
		got.Steps != corrected.Steps || got.SessionCount != corrected.SessionCount ||
		got.Additions != corrected.Additions || got.Deletions != corrected.Deletions || got.FilesChanged != corrected.FilesChanged {
		t.Errorf("late higher-sequence skeleton regressed or blocked hydrated payload: got %+v, want payload from %+v", got, corrected)
	}
	if ids := ParseSessionIDs(got.SessionIDs); len(ids) != 2 || ids[0] != "session-1" || ids[1] != "session-2" {
		t.Errorf("session ids = %v, want hydrated ids", ids)
	}
}

