32	// TestIntegrationMyActivityCostRoundTrip proves the migration-009 cost columns on
33	// the partitioned my_activity persist and read back through the store: a value
34	// round-trips into a monthly partition, absence stays NULL (never a real 0), a
35	// re-upsert with no cost clears it (last-write-wins like the token columns), and a
36	// commit row never carries a cost.
37	func TestIntegrationMyActivityCostRoundTrip(t *testing.T) {
38		_, st := openTest(t)
39		ctx := context.Background()
40		now := time.Now().UTC().Truncate(time.Second)
41	
42		base := MyActivityRow{AccountID: uid("acc1"), Type: "checkpoint", RepoID: uid("r1"), Jurisdiction: "us",
43			SHA: hsha("sha1"), CheckpointID: "cpc", CommittedAt: now, Agent: "claude", HasCheckpoint: true, InputTokens: 100}
44	
45		// 1) Value round-trips through the partition insert ("mixed" exercises the CHECK).
46		cost := 7.25
47		costed := base
48		costed.CostUSD = &cost
49		costed.CostSource = "mixed"
50		if err := st.UpsertMyActivity(ctx, costed); err != nil {
51			t.Fatalf("upsert costed row: %v", err)
52		}
53		if got := oneCheckpointRow(t, st, uid("acc1"), "cpc"); got.CostUSD == nil || *got.CostUSD != 7.25 || got.CostSource != "mixed" {
54			t.Errorf("costed row = %v/%q, want 7.25/mixed", got.CostUSD, got.CostSource)
55		}
56	
57		// 2) Re-upsert with no cost clears the stored value (last-write-wins) → NULL/"".
58		if err := st.UpsertMyActivity(ctx, base); err != nil {
59			t.Fatalf("re-upsert uncosted: %v", err)
60		}
61		if got := oneCheckpointRow(t, st, uid("acc1"), "cpc"); got.CostUSD != nil || got.CostSource != "" {
62			t.Errorf("after clear = %v/%q, want nil/\"\" (NULL, never a real 0)", got.CostUSD, got.CostSource)
63		}
64	
65		// 3) A commit row carries no cost (cost is a checkpoint concept).
66		commitRow := MyActivityRow{AccountID: uid("acc1"), Type: "commit", RepoID: uid("r1"), Jurisdiction: "us",
67			SHA: hsha("sha1"), CommittedAt: now, Agent: "unknown", Additions: 3}
68		if err := st.UpsertMyActivity(ctx, commitRow); err != nil {
69			t.Fatalf("upsert commit: %v", err)
70		}
71		commits, err := st.ListMyActivity(ctx, ActivityQuery{AccountID: uid("acc1"), Type: "commit"})
72		if err != nil {
73			t.Fatal(err)
74		}
75		if len(commits) != 1 || commits[0].CostUSD != nil || commits[0].CostSource != "" {
76			t.Errorf("commit row should carry nil cost, got %+v", commits)
77		}
78	
