	if err != nil {
		t.Fatalf("list my_activity: %v", err)
	}
	for _, r := range rows {
		if r.CheckpointID == cpID {
			return r
		}
	}
	t.Fatalf("checkpoint row %s not found (got %d rows)", cpID, len(rows))
	return MyActivityRow{}
}

// TestIntegrationMyActivityCostRoundTrip proves the migration-009 cost columns on
// the partitioned my_activity persist and read back through the store: a value
// round-trips into a monthly partition, absence stays NULL (never a real 0), a
// re-upsert with no cost clears it (last-write-wins like the token columns), and a
// commit row never carries a cost.
func TestIntegrationMyActivityCostRoundTrip(t *testing.T) {
	_, st := openTest(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Second)

	base := MyActivityRow{AccountID: uid("acc1"), Type: "checkpoint", RepoID: uid("r1"), Jurisdiction: "us",
		SHA: hsha("sha1"), CheckpointID: "cpc", CommittedAt: now, Agent: "claude", HasCheckpoint: true, InputTokens: 100}

	// 1) Value round-trips through the partition insert ("mixed" exercises the CHECK).
	cost := 7.25
	costed := base
	costed.CostUSD = &cost
	costed.CostSource = "mixed"
	if err := st.UpsertMyActivity(ctx, costed); err != nil {
		t.Fatalf("upsert costed row: %v", err)
	}
	if got := oneCheckpointRow(t, st, uid("acc1"), "cpc"); got.CostUSD == nil || *got.CostUSD != 7.25 || got.CostSource != "mixed" {
		t.Errorf("costed row = %v/%q, want 7.25/mixed", got.CostUSD, got.CostSource)
	}

	// 2) Re-upsert with no cost clears the stored value (last-write-wins) → NULL/"".
	if err := st.UpsertMyActivity(ctx, base); err != nil {
		t.Fatalf("re-upsert uncosted: %v", err)
	}
	if got := oneCheckpointRow(t, st, uid("acc1"), "cpc"); got.CostUSD != nil || got.CostSource != "" {
		t.Errorf("after clear = %v/%q, want nil/\"\" (NULL, never a real 0)", got.CostUSD, got.CostSource)
	}

	// 3) A commit row carries no cost (cost is a checkpoint concept).
	commitRow := MyActivityRow{AccountID: uid("acc1"), Type: "commit", RepoID: uid("r1"), Jurisdiction: "us",
		SHA: hsha("sha1"), CommittedAt: now, Agent: "unknown", Additions: 3}
	if err := st.UpsertMyActivity(ctx, commitRow); err != nil {
		t.Fatalf("upsert commit: %v", err)
	}
	commits, err := st.ListMyActivity(ctx, ActivityQuery{AccountID: uid("acc1"), Type: "commit"})
	if err != nil {
		t.Fatal(err)
	}
	if len(commits) != 1 || commits[0].CostUSD != nil || commits[0].CostSource != "" {
		t.Errorf("commit row should carry nil cost, got %+v", commits)
	}

	// 4) A bad cost_source is rejected by the named CHECK on the partitioned table.
	_, err = st.pool.Exec(ctx,
		`INSERT INTO my_activity (account_id, type, origin_key, repo_id, jurisdiction, committed_at, cost_source)
		 VALUES ($1,'checkpoint',$2,$3,'us',$4,'bogus')`, ub("acc1"), ub("r1"), ub("r1"), now)
	if err == nil || !strings.Contains(err.Error(), "my_activity_cost_source_check") {
		t.Errorf("bad cost_source should violate my_activity_cost_source_check, got: %v", err)
	}
}

