// TestIntegrationMyActivityCostMigrationInheritsChild runs migration 009 down then
// up against a my_activity that has a child partition created BEFORE the ALTER —
// the production case, since partitions are provisioned out-of-band before this
// migration runs. It proves the ADD COLUMN / ADD CONSTRAINT on the partitioned
// PARENT cascades to that existing child (Postgres partition inheritance), so no
// child is left without the cost columns.
func TestIntegrationMyActivityCostMigrationInheritsChild(t *testing.T) {
	openTest(t) // ensures the DB is migrated (009 applied) + skip-if-no-DB
	ctx := context.Background()

	// The goose version table (goose_activity_user) lives in the migrate
	// connection's default search_path (public), not `usr`, so the provider must run
	// over a plain-DSN connection — the same connection shape the migrate step uses.
	// A `usr`-search_path connection would see version 0 and mis-replay.
	mg, err := OpenUser(ctx, os.Getenv("ACTIVITY_TEST_DATABASE_URL"))
	if err != nil {
		t.Fatalf("open migrate conn: %v", err)
	}
	defer mg.Close()
	db := stdlib.OpenDBFromPool(mg.pool)
	defer func() { _ = db.Close() }()
	provider, err := goose.NewProvider(goose.DialectPostgres, db, usermigrations.FS, goose.WithTableName(gooseTableUser))
	if err != nil {
		t.Fatalf("goose provider: %v", err)
	}

	// Roll 009 back: the cost columns drop off the parent and every child.
	if _, err := provider.Down(ctx); err != nil {
		t.Fatalf("goose down 009: %v", err)
	}
	// Always re-apply on the way out so the shared test DB is left at the latest
	// version for subsequent tests (runs even on t.Fatal via Goexit).
	t.Cleanup(func() { _, _ = provider.Up(context.Background()) })

	// A child partition provisioned BEFORE the re-applied ALTER (a far-future month
	// so it can't collide with the harness-seeded partitions), qualified to usr since
	// the migrate connection's search_path is public. It inherits the current
	// cost-less parent shape.
	const child = "my_activity_pcostmig"
	if _, err := mg.pool.Exec(ctx,
		`CREATE TABLE IF NOT EXISTS usr.`+child+` PARTITION OF usr.my_activity FOR VALUES FROM ('2099-01-01') TO ('2099-02-01')`); err != nil {
		t.Fatalf("create pre-ALTER child: %v", err)
	}
	t.Cleanup(func() { _, _ = mg.pool.Exec(context.Background(), `DROP TABLE IF EXISTS usr.`+child) })

	if childHasColumn(ctx, t, mg, child, "cost_usd") {
		t.Fatal("pre-ALTER child unexpectedly already has cost_usd")
	}

	// Re-apply 009: the parent ALTER must cascade to the existing child.
	if _, err := provider.Up(ctx); err != nil {
		t.Fatalf("goose up 009: %v", err)
	}

	if !childHasColumn(ctx, t, mg, child, "cost_usd") || !childHasColumn(ctx, t, mg, child, "cost_source") {
		t.Error("existing child did NOT inherit the cost columns from the parent ALTER")
	}

	// The CHECK constraint is inherited too — a bad cost_source routed to the child
	// (2099-01) is rejected.
	_, err = mg.pool.Exec(ctx,
		`INSERT INTO usr.my_activity (account_id, type, origin_key, repo_id, jurisdiction, committed_at, cost_source)
		 VALUES ($1,'checkpoint',$2,$3,'us','2099-01-15','bogus')`, ub("acc1"), ub("r1"), ub("r1"))
	if err == nil || !strings.Contains(err.Error(), "my_activity_cost_source_check") {
		t.Errorf("child should enforce inherited cost_source CHECK, got: %v", err)
	}
