// TestIntegrationGetCheckpointReadsCost proves GetCheckpoint loads cost_usd /
// cost_source — the field source for the commit-first (forwardCheckpointForCommit)
// and re-attribution checkpoint forwards, which read the stored checkpoint through
// here rather than a freshly-parsed row.
func TestIntegrationGetCheckpointReadsCost(t *testing.T) {
	repo, _ := openTest(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Second)

	cost := 9.5
	if _, err := repo.UpsertCheckpoint(ctx, Checkpoint{RepoID: uid("r1"), CheckpointID: "cpg",
		CreatedAt: now, PrimaryAgent: "claude", CostUSD: &cost, CostSource: "estimated"}); err != nil {
		t.Fatalf("upsert costed checkpoint: %v", err)
	}
	cp, ok, err := repo.GetCheckpoint(ctx, uid("r1"), "cpg")
	if err != nil || !ok {
		t.Fatalf("get checkpoint: ok=%v err=%v", ok, err)
	}
	if cp.CostUSD == nil || *cp.CostUSD != 9.5 || cp.CostSource != "estimated" {
		t.Errorf("GetCheckpoint cost = %v/%q, want 9.5/estimated", cp.CostUSD, cp.CostSource)
	}

	// A cost-less checkpoint reads back nil/"" (unknown, never a real 0).
	if _, err := repo.UpsertCheckpoint(ctx, Checkpoint{RepoID: uid("r1"), CheckpointID: "cpg2",
		CreatedAt: now, PrimaryAgent: "claude"}); err != nil {
		t.Fatalf("upsert cost-less checkpoint: %v", err)
	}
	cp2, ok, err := repo.GetCheckpoint(ctx, uid("r1"), "cpg2")
	if err != nil || !ok {
		t.Fatalf("get cost-less checkpoint: ok=%v err=%v", ok, err)
