// childHasColumn reports whether the usr-schema table has the given column.
func childHasColumn(ctx context.Context, t *testing.T, st *UserStore, table, column string) bool {
	t.Helper()
	var exists bool
	if err := st.pool.QueryRow(ctx,
		`SELECT EXISTS (SELECT 1 FROM information_schema.columns
		 WHERE table_schema='usr' AND table_name=$1 AND column_name=$2)`, table, column).Scan(&exists); err != nil {
		t.Fatalf("column lookup %s.%s: %v", table, column, err)
	}
	return exists
}

