func (c *Cell) ForwardCheckpointActivity(r *Repo, author *User, checkpointID string, at time.Time, hydrated bool) {
	c.w.t.Helper()
	cp := store.Checkpoint{}
	if hydrated {
		cp = store.Checkpoint{
			PrimaryAgent: "claude", PayloadHydrationState: store.HydrationHydrated,
			Steps: 1, SessionCount: 1,
			InputTokens: 1, OutputTokens: 1,
			SessionIDs: store.MarshalSessionIDs([]string{"session-1"}),
		}
	}
	c.forwardCheckpointActivity(r, author, checkpointID, at, cp)
}

// ForwardFailedCheckpointActivity models the bare row MarkCheckpointFailed
// inserts after payload fetch failure. The row exists, but carries no usable
// payload and therefore must cross cells as a skeleton phase.
func (c *Cell) ForwardFailedCheckpointActivity(r *Repo, author *User, checkpointID string, at time.Time) {
	c.w.t.Helper()
	c.forwardCheckpointActivity(r, author, checkpointID, at, store.Checkpoint{
		PayloadHydrationState: store.HydrationFailed,
	})
}

func (c *Cell) forwardCheckpointActivity(r *Repo, author *User, checkpointID string, at time.Time, cp store.Checkpoint) {
	c.w.t.Helper()
	ev := ingest.CheckpointActivityEvent(
		coreapi.Account{AccountID: author.account, HomeJurisdiction: c.w.core.getHome(author.account)},
		c.jur, r.group, r.In(c), idSHA("activity-"+checkpointID), checkpointID, at, cp, store.StateShipped,
	)
	if err := forwarder.NewPublisher(c.w.dests, c.jur, false).PublishUserActivity(c.ctx, ev); err != nil {
		c.w.t.Fatalf("%s forward checkpoint activity: %v", c.jur, err)
	}
}

// Push publishes the repo_refs_v1 ref event(s) for a push landing in this cell,
// which the ingester indexes and forwards /me activity for (to the commit author's
// home cell). No sessions → a plain commit; one or more → a checkpoint push (the
// checkpoint ref first, so hydration precedes the anchoring commit's enriched
// forward). Push the same Commit in two cells to model one commit reaching two
// placements (the dedup scenario).
func (c *Cell) Push(r *Repo, commit Commit, sessions ...string) {
	c.ensureFlow()
	if len(sessions) == 0 {
		c.pushCommit(r, commit)
		return
	}
	c.pushCheckpoint(r, commit, sessions)
}

// pushCommit publishes the ref event for a plain commit push. The fixed default
// commit date is fine for the activity scenarios, which assert the store (no /me
// window); the day-scoped rollup scenarios mint dated commits via w.CommitOn.
func (c *Cell) pushCommit(r *Repo, commit Commit) {
	sha := commit.sha
	c.repoAPI.setCommits(sha, []repoapi.Commit{repoAPICommit(commit)})
	// The branch now answers ref listings at this tip — what the default-branch
	// job's live tip resolution reads.
	c.repoAPI.setBranchRef("refs/heads/main", sha)
	c.publishRef(ingest.RefEvent{
		RepoID: r.In(c), RefName: "refs/heads/main", RefOp: "update",
		NewTarget: sha, OldTarget: "old-" + sha,

