	author := w.User(home)

	const checkpointID = "c0ffee-cost-02"
	at := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
	unstorable := 1e9 // >= the NUMERIC(14,6) column's 1e8 bound
	eu.ForwardCheckpointActivityWithCost(repo, author, checkpointID, at, &unstorable, "reported")

