package multicellular

import (
	"testing"
	"time"

	"github.com/entirehq/entire-api/internal/multicellular/events"
	"github.com/entirehq/entire-api/internal/multicellular/harness"
)

// A push to a mirror in one jurisdiction, whose commit is authored by a user homed
// in another, attributes to that user on their home cell — via the shared
// repo_group origin, not the mirror's placement id.
func TestActivityAttributesToHomeJurisdiction(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us")
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo)) // the mirror lives in eu
	author := w.User(home)                // but the author is homed in us

	eu.Receives(events.Push(repo, w.Commit(author)))

	w.Settle()
	home.AssertActivity(author, harness.Activity{Rows: 1, AttributedTo: repo})
}

// The same commit pushed to two placements of one logical repo collapses to a
// single activity row on the home cell — no per-placement inflation.
func TestActivityDedupsAcrossPlacements(t *testing.T) {
	w := harness.New(t)
	us, eu := w.Cell("us"), w.Cell("eu")
	repo := w.Repo()
	us.Receives(events.RepoCreated(repo))
	eu.Receives(events.RepoCreated(repo))
	author := w.User(us)

	commit := w.Commit(author)
	us.Receives(events.Push(repo, commit)) // one commit...
	eu.Receives(events.Push(repo, commit)) // ...reaching both placements

	w.Settle()
	us.AssertActivity(author, harness.Activity{Rows: 1, AttributedTo: repo}) // one row, not one per placement
}

// A commit-first checkpoint push crosses from its placement cell to the author's
// home as two immediate forwards: an unknown/zero skeleton, then the hydrated
// agent/count payload. JetStream's production-like duplicate window must retain
// the enrichment as a distinct wire identity; the home store must finish with
// the hydrated values rather than the skeleton. Removing the checkpoint payload
// fingerprint makes this fail as unknown/0/0.
func TestCheckpointHydrationSurvivesCrossCellDedup(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us", harness.ActivityConsumerPaused())
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	author := w.User(home)

	const checkpointID = "c0ffee01"
	at := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, false)) // commit-first skeleton
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, true))  // immediate hydration
	home.AssertQueuedActivityMessages(2)                                          // skeleton + hydration are distinct wire identities
	home.StartActivityConsumer()                                                  // consume after broker dedup chose what survived

	w.Settle()
	home.AssertCheckpointActivity(checkpointID, "claude", 1, 1)
}

// Hydration can publish before the commit job's stale snapshot: the jobs run
// independently, and the commit path can read GetCheckpoint before hydration but
// reach the home stream afterward. That later skeleton has the HIGHER sequence,
// so the semantic hydrated phase — not sequence alone — must keep the rich row.
// Replacing the phase+sequence gate with sequence-only makes this fail unknown/0/0.
func TestCheckpointHydrationOutranksLaterCrossCellSkeleton(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us", harness.ActivityConsumerPaused())
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	author := w.User(home)

	const checkpointID = "c0ffee02"
	at := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, true))  // hydration wins semantically
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, false)) // later, higher-sequence skeleton
	home.AssertQueuedActivityMessages(2)
	home.StartActivityConsumer()

	w.Settle()
	home.AssertCheckpointActivity(checkpointID, "claude", 1, 1)
}

// A failed payload fetch leaves a real checkpoint row, so GetCheckpoint reports
// it present. If that presence is mistaken for hydration, a later failed-placeholder
// forward has the higher sequence in the hydrated phase and overwrites the genuine
// payload at the author's home. The explicit failed hydration state must instead
// keep it in the skeleton phase, where it cannot outrank the earlier rich payload.
func TestFailedCheckpointPlaceholderCannotOutrankCrossCellHydration(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us", harness.ActivityConsumerPaused())
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	author := w.User(home)

	const checkpointID = "c0ffee03"
	at := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, true))
	eu.Receives(events.FailedCheckpointActivity(repo, author, checkpointID, at)) // later existing-but-empty row
	home.AssertQueuedActivityMessages(2)
	home.StartActivityConsumer()

	w.Settle()
	home.AssertCheckpointActivity(checkpointID, "claude", 1, 1)
}

// A ref-backed checkpoint push (its own per-checkpoint ref, NO anchoring branch
// commit) in one jurisdiction still lights /me on the author's home cell: the
// row is attributed by the checkpoint commit's own author — the identity the
// CLI stamps — keyed on the shared repo_group origin. Without the ref forward
// (ingest.Flow.forwardRefCheckpoint) this push forwards nothing, and the
// session stays invisible on /me until a trailer-linked commit lands (which
// here never does).
func TestRefCheckpointActivityAttributesToAuthorHome(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us")
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo)) // the placement lives in eu
	author := w.User(home)                // but the session's author is homed in us

	eu.Receives(events.RefCheckpointPush(repo, w.Commit(author), "sess-ref-1"))

	w.Settle()
	home.AssertActivity(author, harness.Activity{Rows: 1, AttributedTo: repo})
}

// Both checkpoint backends route imports to the authenticated importer's home,
// not the checkpoint commit author's home, keyed by the repo's shared origin.
func TestImportedCheckpointActivityAttributesToImporterHome(t *testing.T) {
	cases := []struct {
		name string
		push func(*harness.Repo, *harness.User, harness.Commit) harness.Event
	}{
		{"branch", func(r *harness.Repo, u *harness.User, c harness.Commit) harness.Event {
			return events.ImportedCheckpointPush(r, u, c, "sess-imported-branch")
		}},
		{"ref", func(r *harness.Repo, u *harness.User, c harness.Commit) harness.Event {
			return events.ImportedRefCheckpointPush(r, u, c, "sess-imported-ref")
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			w := harness.New(t)
			home, eu, other := w.Cell("us"), w.Cell("eu"), w.Cell("ap")
			repo := w.Repo()
			eu.Receives(events.RepoCreated(repo))
			importer, checkpointAuthor := w.User(home), w.User(other)
			eu.Receives(tc.push(repo, importer, w.Commit(checkpointAuthor)))

			w.Settle()
			home.AssertActivity(importer, harness.Activity{Rows: 1, AttributedTo: repo})
			other.AssertNoActivityWritten()
		})
	}
}

// A transient source-to-home publish failure must nak the imported-checkpoint
// index job. JetStream redelivery then retries the forward and the importer's
// home receives the activity exactly once.
func TestImportedCheckpointActivityForwardFailureRedelivers(t *testing.T) {
	w := harness.New(t)
	home, eu, other := w.Cell("us"), w.Cell("eu"), w.Cell("ap")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	importer, checkpointAuthor := w.User(home), w.User(other)
	eu.FailNextActivityForwardTo(home)

	eu.Receives(events.ImportedCheckpointPush(repo, importer, w.Commit(checkpointAuthor), "sess-imported-retry"))

	w.Settle()
	eu.AssertActivityForwardRetried(home)
	home.AssertActivity(importer, harness.Activity{Rows: 1, AttributedTo: repo})
	other.AssertNoActivityWritten()
}

// A user's activity is stored in their home region and there ALONE: a push in one
// cell forwards to the author's home cell, and a third cell that is neither the
// placement origin nor the author's home holds none of it — activity residency
// containment (the same guarantee TestSettingsResidencyContainment asserts for
// settings), across a real three-cell forward.
func TestActivityResidencyContainment(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us") // the author's home
	eu := w.Cell("eu")   // hosts the placement / push origin
	ap := w.Cell("ap")   // hosts nothing of repo, and not the author's home
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	author := w.User(home)

	eu.Receives(events.Push(repo, w.Commit(author)))

	w.Settle()
	home.AssertActivity(author, harness.Activity{Rows: 1, AttributedTo: repo}) // stored in the author's home region
	ap.AssertNoActivityWritten()                                               // and nowhere else — residency contained
}

