// TestParseSessionReportedCostOnAggregateTokenUsage covers the no-model_usage
// shape (a session that carries only an aggregate token_usage block): the same
// preference applies — a reported cost is trusted, and its absence falls back to
// pricing the aggregate counts against the session's single model id.
func TestParseSessionReportedCostOnAggregateTokenUsage(t *testing.T) {
	metaReported := `{"session_id":"s","agent":"claude","checkpoints_count":1,"model":"claude-sonnet-5",
		"token_usage":{"input_tokens":1000000,"output_tokens":1000000,"cost_usd":4.25,"cost_source":"reported"}}`
	ps, ok := parseSession([]byte(metaReported), nil)
	if !ok {
		t.Fatal("parseSession failed")
	}
	if tu := ps.Info.TokenUsage; tu == nil || tu.CostUSD == nil || *tu.CostUSD != 4.25 || tu.CostSource != "reported" {
		t.Errorf("session cost = %+v, want 4.25/reported (aggregate block, no model_usage)", ps.Info.TokenUsage)
	}

	metaNoCost := `{"session_id":"s","agent":"claude","checkpoints_count":1,"model":"claude-sonnet-5",
		"token_usage":{"input_tokens":1000000,"output_tokens":1000000}}`
	psE, ok := parseSession([]byte(metaNoCost), nil)
	if !ok {
		t.Fatal("parseSession failed (no cost)")
	}
	if tu := psE.Info.TokenUsage; tu == nil || tu.CostUSD == nil || *tu.CostUSD != 18.0 || tu.CostSource != "estimated" {
		t.Errorf("session cost = %+v, want 18.0/estimated (aggregate fallback)", psE.Info.TokenUsage)
	}
}

// TestParseSessionComputedCostOverRangeDropped proves a computed cost beyond the
// NUMERIC(14,6) column range (>= 1e8) is dropped to nil rather than persisted (it
// would fault the INSERT and poison-loop the consumer). claude-opus-4-8 output is
// $25/MTok, so 5e12 output tokens compute to 1.25e8 — over range.
func TestParseSessionComputedCostOverRangeDropped(t *testing.T) {
	meta := `{"session_id":"s","agent":"claude","checkpoints_count":1,
		"token_usage":{"output_tokens":5000000000000},
		"model_usage":[
			{"model":"claude-opus-4-8","token_usage":{"output_tokens":5000000000000}}
		]}`
	ps, ok := parseSession([]byte(meta), nil)
	if !ok {
		t.Fatal("parseSession failed")
	}
	if tu := ps.Info.TokenUsage; tu == nil || tu.CostUSD != nil || tu.CostSource != "" {
		t.Errorf("session cost = %+v, want nil/\"\" (over-range computed cost dropped)", ps.Info.TokenUsage)
	}
	if mu := ps.Info.ModelUsage[0].TokenUsage; mu.CostUSD != nil {
		t.Errorf("bucket cost = %v, want nil (over-range dropped)", *mu.CostUSD)
	}
}

