package store

import (
	"context"
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"testing"
	"time"
)

func TestResolveSessionNamePrecedence(t *testing.T) {
	cases := []struct{ custom, generated, display, want string }{
		{"My name", "Gen", "Disp", "My name"},
		{"   ", "Gen", "Disp", "Gen"}, // whitespace custom ignored
		{"", "   ", "Disp", "Disp"},   // whitespace generated ignored
		{"", "", "Disp", "Disp"},      // heuristic fallback
	}
	for _, c := range cases {
		if got := resolveSessionName(c.custom, c.generated, c.display); got != c.want {
			t.Errorf("resolveSessionName(%q,%q,%q) = %q, want %q", c.custom, c.generated, c.display, got, c.want)
		}
	}
}

func TestBuildSessionDisplayName(t *testing.T) {
	if got := buildSessionDisplayName("  do the thing  ", "irrelevant"); got != "do the thing" {
		t.Errorf("prompt wins, got %q", got)
	}
	if got := buildSessionDisplayName("", "fix: the bug\nbody text"); got != "fix: the bug" {
		t.Errorf("commit subject fallback, got %q", got)
	}
	if got := buildSessionDisplayName("", ""); got != "Untitled session" {
		t.Errorf("untitled fallback, got %q", got)
	}
	long := strings.Repeat("x", 300)
	if got := buildSessionDisplayName(long, ""); len([]rune(got)) != sessionDisplayNameMaxChars {
		t.Errorf("clamp to %d, got %d", sessionDisplayNameMaxChars, len([]rune(got)))
	}
}

